const fs=require('node:fs/promises');const path=require('node:path');
const {AssetStore}=require('../../desktop/asset-store.cjs');const {ThemeLibrary}=require('../../desktop/theme-library.cjs');const {PreferencesStore}=require('../../desktop/preferences-store.cjs');const {ThemeRevisionStore}=require('../../desktop/theme-revision-store.cjs');const {ProjectBindingsStore}=require('../../desktop/project-bindings-store.cjs');const {BackupService}=require('../../desktop/backup-service.cjs');const {documentFromLegacy}=require('../../core/theme-schema.cjs');const {PNG}=require('pngjs');
function doc(){return documentFromLegacy({schemaVersion:1,themeId:'graphite',appearance:{opacity:80,blur:28,radius:8,wallpaper:null}});}
function png(color=255){const p=new PNG({width:8,height:8});p.data.fill(color);return PNG.sync.write(p);}
async function stores(dir,deps={}){await fs.mkdir(dir,{recursive:true});const assets=new AssetStore(path.join(dir,'assets'));await assets.init();const library=new ThemeLibrary(path.join(dir,'theme-library.json'),{assets});await library.load();const preferenceStore=new PreferencesStore(path.join(dir,'preferences.json'));await preferenceStore.load();const revisions=new ThemeRevisionStore(path.join(dir,'theme-revisions'),{assets});await revisions.load();const bindings=new ProjectBindingsStore(path.join(dir,'project-bindings.json'));await bindings.load();const result={assets,library,preferenceStore,revisions,bindings};result.backup=new BackupService({userData:dir,...result,...deps});return result;}
async function seed(s,dir){const asset=await s.assets.importImage(png(),s.assets.beginImport());const d=doc();d.wallpaper.assetId=asset.record.id;const t=await s.library.saveNew(d,'迁移主题');await s.library.favorite(t.id,true);await fs.writeFile(path.join(dir,'appearance.json'),JSON.stringify({schemaVersion:1,document:t.document}));await s.preferenceStore.save({...s.preferenceStore.current,performance:{mode:'auto',batteryAware:true,maxTier:'powersave'},shortcuts:{enabled:true,bindings:{quickSwitcher:'Ctrl+Shift+Q'}},notifications:{sound:true,desktop:true,onFailed:true},automation:{mode:'system',lightThemeId:'graphite',darkThemeId:'graphite',rules:[]}});await s.bindings.saveBinding({projectKey:'redacted-project-key',themeId:t.id});const revision=await s.revisions.record({themeId:t.id,document:t.document,source:'save'});return{theme:t,assetId:asset.record.id,revision};}
module.exports={stores,seed,doc,png};
